package vn.contractgovernance.api.control;

import java.sql.Timestamp;
import java.time.Clock;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.approval.ApprovalInputs;
import vn.contractgovernance.api.policy.PolicyAccess;
import vn.contractgovernance.api.identity.UserDirectory;
import static vn.contractgovernance.api.change.ChangeService.id;

@Service
public class ControlApproval {
 private final EntityStore store;private final ControlService controls;private final ControlEvidence evidence;private final UserDirectory users;private final JsonSupport json;private final Clock clock;private final CalendarService calendar;private final PolicyAccess policies;private final CommandExecutor commands;private final ContractRegistry schemas;private final AuditService audit;private final ApprovalInputs inputs;private final vn.contractgovernance.api.contract.ContractLifecycle lifecycle;
 public ControlApproval(EntityStore store,ControlService controls,ControlEvidence evidence,UserDirectory users,JsonSupport json,Clock clock,CalendarService calendar,PolicyAccess policies,CommandExecutor commands,ContractRegistry schemas,AuditService audit,ApprovalInputs inputs,vn.contractgovernance.api.contract.ContractLifecycle lifecycle){this.store=store;this.controls=controls;this.evidence=evidence;this.users=users;this.json=json;this.clock=clock;this.calendar=calendar;this.policies=policies;this.commands=commands;this.schemas=schemas;this.audit=audit;this.inputs=inputs;this.lifecycle=lifecycle;}
 private ObjectNode step(String level,UUID reviewer,String state){var b=json.object().put("level",level).put("reviewerId",reviewer.toString()).put("state",state);b.putNull("decidedBy").putNull("decisionAt").putNull("reason");return b;}
 public EntityStore.Entity submit(EntityStore.Entity r,JsonNode request,Actor actor){controls.state(r,"DRAFT");controls.sourceGuard(r);boolean direct=Set.of("SUSPEND","STOP").contains(r.body().path("kind").asString());boolean l2=r.body().path("kind").asString().equals("TERMINATE");if(direct?(request.hasNonNull("l1ReviewerId")||request.hasNonNull("l2ReviewerId")):(!request.hasNonNull("l1ReviewerId")||(l2?!request.hasNonNull("l2ReviewerId"):request.hasNonNull("l2ReviewerId"))))throw ApiException.validation("/l1ReviewerId","Reviewer không khớp route control.");var f=controls.freeze(r,actor);var b=(ObjectNode)r.body().deepCopy();b.set("contributorIds",f.revision().path("contributorIds"));if(direct){b.put("state","REQUESTED");return controls.save(r,b,actor,"SUBMIT",request.path("reason").asString());}var steps=json.array().add(step("L1",id(request,"l1ReviewerId"),"PENDING"));if(l2)steps.add(step("L2",id(request,"l2ReviewerId"),"WAITING"));eligible(r,steps);var policy=policies.requireApplicable();var rb=json.object().put("createdAt",controls.now()).put("updatedAt",controls.now()).put("branchId",r.branchId().toString()).put("targetKind","CONTROL_REQUEST").put("targetId",r.id().toString()).put("revisionId",f.id().toString()).put("state","OPEN").put("policyVersionId",policy.id().toString()).put("dueAt",JsonSupport.timestamp(calendar.dueByBusinessDays(clock.instant(),policy.body().path("config").path("reviewDueWorkingDays").asInt()))).put("authorityChecked",false);rb.set("steps",steps);rb.set("evidenceChecks",json.array());rb.set("mandatoryChecks",store.require("Contract",id(r.body(),"contractId")).body().path("mandatoryChecks").deepCopy());rb.set("allowedActions",json.array());rb.set("blockedActions",json.array());var round=store.create("Round",UUID.randomUUID(),r.branchId(),rb);schemas.validateSchema("Round",round.body());audit.record(actor,"CREATE",round,null);b.put("state","IN_REVIEW").put("roundId",round.id().toString());return controls.save(r,b,actor,"SUBMIT",request.path("reason").asString());}
 private void eligible(EntityStore.Entity r,JsonNode steps){eligible(r,steps,false);}
 private void eligible(EntityStore.Entity r,JsonNode steps,boolean historical){var seen=new HashSet<UUID>();for(var step:steps){if(historical&&step.path("state").asString().equals("APPROVED"))continue;UUID reviewer=id(step,"reviewerId");if(!seen.add(reviewer))throw ApiException.of("SOD_VIOLATION","L1/L2 phải khác nhau.");users.requireEligible(reviewer,r.branchId(),step.path("level").asString().equals("L1")?"CHECKER":"MANAGER",controls.contributors(r));evidence.manifest(r,evidence.ids(r.body().path("evidenceFileIds")),users.actor(reviewer),false);}}
 public EntityStore.Entity requireRound(UUID id,Actor actor){var round=store.require("Round",id);if(!round.body().path("targetKind").asString().equals("CONTROL_REQUEST"))throw ApiException.of("NOT_FOUND","Không phải Control Round.");var r=controls.require(id(round.body(),"targetId"),actor);if(!Objects.equals(round.branchId(),r.branchId()))throw ApiException.of("NOT_FOUND","Sai round scope.");return round;}
 private ObjectNode step(JsonNode body,String level){for(var step:body.path("steps"))if(step.path("level").asString().equals(level))return (ObjectNode)step;throw ApiException.validation("/level","Level không thuộc round.");}
 private void authorize(EntityStore.Entity round,JsonNode request,Actor actor){var r=controls.require(id(round.body(),"targetId"),actor);if(controls.contributors(r).contains(actor.id()))throw ApiException.of("SOD_VIOLATION","Reviewer đã contribute control.");if(request.path("action").asString().equals("REASSIGN")){users.actor(actor.id()).requireRole("MANAGER");return;}String level=request.path("action").asString().equals("VERIFY_EVIDENCE")?"L1":request.path("level").asString();var step=step(round.body(),level);if(!step.path("reviewerId").asString().equals(actor.id().toString()))throw ApiException.of("ROLE_FORBIDDEN","Không phải assigned reviewer.");eligible(r,json.array().add(step));}
 private void open(EntityStore.Entity round,EntityStore.Entity r){controls.state(r,"IN_REVIEW");if(!round.body().path("state").asString().equals("OPEN")||!r.body().path("roundId").asString().equals(round.id().toString()))throw ApiException.of("STATE_CONFLICT","Round không còn current/open.");}
 private void checked(EntityStore.Entity r,JsonNode body,ControlService.Frozen f,Actor actor){controls.current(r,f,actor);if(!body.path("authorityChecked").asBoolean())throw ApiException.of("AUTHORITY_INVALID","Authority chưa checked.");var ids=evidence.ids(f.revision().path("evidenceFileIds"));var seen=new HashSet<UUID>();for(var check:body.path("evidenceChecks")){if(!check.path("result").asString().equals("PASS"))throw ApiException.of("READINESS_BLOCKED","Control evidence chưa human PASS.");seen.add(id(check,"fileId"));evidence.nonfuture(check.path("checkedAt"));}if(!seen.containsAll(ids))throw ApiException.of("READINESS_BLOCKED","Mọi source evidence cần human PASS.");var codes=new HashSet<String>();for(var check:body.path("mandatoryChecks")){if(!check.path("result").asString().equals("PASS"))throw ApiException.of("LEGAL_REVIEW_REQUIRED","Mandatory condition chưa PASS.");codes.add(check.path("code").asString());var refs=evidence.ids(check.path("evidenceFileIds"));if(refs.isEmpty()||!ids.containsAll(refs))throw ApiException.of("LEGAL_REVIEW_REQUIRED","Mandatory evidence không thuộc exact control source.");evidence.manifest(r,refs,actor,false);evidence.nonfuture(check.path("checkedAt"));}if(!codes.contains("AUTHORITY_CURRENT")||!codes.contains("LEGAL_CONDITION"))throw ApiException.of("LEGAL_REVIEW_REQUIRED","Cần authority và reviewed ground/notice condition.");}
 public ApiResult command(UUID id,JsonNode request,String tag,String key,Actor actor){var preview=requireRound(id,actor);authorize(preview,request,actor);ETags.require(tag);var cid=id(controls.require(id(preview.body(),"targetId"),actor).body(),"contractId");return commands.execute(actor,key,"POST","/api/v1/rounds/"+id+"/commands",request,tag,()->authorize(requireRound(id,actor),request,actor),()->lifecycle.maintain(cid,actor),()->{var r=controls.lock(id(preview.body(),"targetId"));var round=store.lock("Round",id);authorize(round,request,actor);ETags.check(tag,round.version());open(round,r);if(!request.path("action").asString().equals("REASSIGN")){var active=step(round.body(),request.path("action").asString().equals("VERIFY_EVIDENCE")?"L1":request.path("level").asString());if(!active.path("state").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","Review step không pending.");}var f=controls.revision(id(round.body(),"revisionId"),r.id());var b=(ObjectNode)round.body().deepCopy();String action=request.path("action").asString();if(action.equals("VERIFY_EVIDENCE")){controls.current(r,f,actor);var ids=evidence.ids(f.revision().path("evidenceFileIds"));var seen=new HashSet<UUID>();for(var check:request.path("checks")){UUID file=id(check,"fileId");if(!seen.add(file)||!ids.contains(file))throw ApiException.validation("/checks","Check ngoài source hoặc trùng.");evidence.nonfuture(check.path("checkedAt"));}inputs.retainConditions(b.path("mandatoryChecks"),request.path("mandatoryChecks"));for(var check:request.path("mandatoryChecks")){evidence.nonfuture(check.path("checkedAt"));var refs=evidence.ids(check.path("evidenceFileIds"));if(!ids.containsAll(refs))throw ApiException.validation("/mandatoryChecks","Evidence ngoài source.");evidence.manifest(r,refs,actor,true);}b.set("evidenceChecks",request.path("checks"));b.set("mandatoryChecks",request.path("mandatoryChecks"));b.set("authorityChecked",request.path("authorityChecked"));store.jdbc().update("insert into cg_round_assessment(id,round_id,actor_id,assessment,recorded_at) values(?,?,?,?::jsonb,?)",UUID.randomUUID(),id,actor.id(),json.stringify(request),Timestamp.from(clock.instant()));}else if(action.equals("REASSIGN")){var step=step(b,request.path("level").asString());if(!Set.of("PENDING","WAITING").contains(step.path("state").asString()))throw ApiException.of("STATE_CONFLICT","Step đã quyết định.");UUID old=id(step,"reviewerId");if(old.equals(id(request,"reviewerId")))throw ApiException.validation("/reviewerId","Cần reviewer khác.");step.set("reviewerId",request.path("reviewerId"));eligible(r,b.path("steps"),true);store.jdbc().update("insert into cg_round_reassignment(id,round_id,level,old_reviewer_id,new_reviewer_id,actor_id,reason,recorded_at) values(?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,request.path("level").asString(),old,id(step,"reviewerId"),actor.id(),request.path("reason").asString(),Timestamp.from(clock.instant()));if(request.path("level").asString().equals("L1")){b.set("evidenceChecks",json.array());b.put("authorityChecked",false);}}else{var step=step(b,request.path("level").asString());if(action.equals("APPROVE")){checked(r,b,f,actor);eligible(r,b.path("steps"),true);step.put("state","APPROVED");if(b.path("steps").size()==1||request.path("level").asString().equals("L2")){b.put("state","APPROVED");var rb=(ObjectNode)r.body().deepCopy();rb.put("state","APPROVED");controls.save(r,rb,actor,"APPROVE",request.path("reason").asString());}else step(b,"L2").put("state","PENDING");}else if(Set.of("RETURN","REJECT").contains(action)){b.put("state",action.equals("RETURN")?"RETURNED":"REJECTED");step.put("state",action.equals("RETURN")?"RETURNED":"REJECTED");cancelUndecided(b);var rb=(ObjectNode)r.body().deepCopy();rb.put("state",action.equals("RETURN")?"DRAFT":"REJECTED");controls.save(r,rb,actor,action,request.path("reason").asString());}else throw ApiException.validation("/action","Unsupported action.");step.put("decidedBy",actor.id().toString()).put("decisionAt",controls.now()).put("reason",request.path("reason").asString());store.jdbc().update("insert into cg_round_decision(round_id,level,actor_id,action,reason,decided_at) values(?,?,?,?,?,?)",id,request.path("level").asString(),actor.id(),action,request.path("reason").asString(),Timestamp.from(clock.instant()));}b.put("updatedAt",controls.now());var next=store.update(round,b);schemas.validateSchema("Round",next.body());audit.record(actor,action,next,request.hasNonNull("reason")?request.path("reason").asString():null);return ApiResult.ok(project(next,actor));});}
 private void cancelUndecided(ObjectNode body){for(var step:body.path("steps"))if(Set.of("PENDING","WAITING").contains(step.path("state").asString()))((ObjectNode)step).put("state","CANCELLED");}
 public void cancelRound(EntityStore.Entity r,Actor actor){if(!r.body().hasNonNull("roundId"))return;var round=store.lock("Round",id(r.body(),"roundId"));if(!round.body().path("state").asString().equals("OPEN"))return;var b=(ObjectNode)round.body().deepCopy();b.put("state","CANCELLED").put("updatedAt",controls.now());cancelUndecided(b);audit.record(actor,"CANCEL",store.update(round,b),"Control applicability ended or source cancelled");}
 public void requireApproved(EntityStore.Entity r,ControlService.Frozen f,Actor actor){var round=store.require("Round",id(r.body(),"roundId"));if(!round.body().path("state").asString().equals("APPROVED")||!round.body().path("revisionId").asString().equals(f.id().toString()))throw ApiException.of("READINESS_BLOCKED","Control approval source mismatch.");checked(r,round.body(),f,actor);}
 public JsonNode snapshot(UUID id,Actor actor){var round=requireRound(id,actor);var revision=(ObjectNode)controls.revision(id(round.body(),"revisionId"),id(round.body(),"targetId")).revision().deepCopy();if(redacted(actor))revision.put("reason","[REDACTED]");var result=json.object().put("targetKind","CONTROL_REQUEST");result.set("revision",revision);return result;}
 private boolean redacted(Actor actor){return actor.hasRole("AUDITOR")&&!actor.hasAnyRole("MAKER","CHECKER","MANAGER","DATA_OFFICER")&&!actor.hasPermission("SENSITIVE_READ");}
 public JsonNode project(EntityStore.Entity round,Actor actor){var b=(ObjectNode)round.body().deepCopy();var allowed=json.array();var blocked=json.array();if(b.path("state").asString().equals("OPEN"))for(String action:List.of("VERIFY_EVIDENCE","APPROVE","RETURN","REJECT","REASSIGN")){var request=json.object().put("action",action);String level="L1";for(var step:b.path("steps"))if(step.path("reviewerId").asString().equals(actor.id().toString())&&step.path("state").asString().equals("PENDING"))level=step.path("level").asString();request.put("level",level);try{authorize(round,request,actor);var r=controls.require(id(b,"targetId"),actor);open(round,r);if(!action.equals("REASSIGN")&&!step(b,action.equals("VERIFY_EVIDENCE")?"L1":level).path("state").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","Review step không pending.");if(action.equals("APPROVE"))checked(r,b,controls.revision(id(b,"revisionId"),r.id()),actor);allowed.add(action);}catch(ApiException e){if(actor.hasAnyRole("CHECKER","MANAGER"))blocked.add(json.object().put("action",action).put("code",e.code()).put("reason",e.getMessage()));}}if(redacted(actor)){for(var check:b.path("evidenceChecks")){((ObjectNode)check).put("basis","[REDACTED]").put("reason","[REDACTED]");}for(var check:b.path("mandatoryChecks"))((ObjectNode)check).put("basis","[REDACTED]");for(var step:b.path("steps"))if(step.hasNonNull("reason"))((ObjectNode)step).put("reason","[REDACTED]");}b.set("allowedActions",allowed);b.set("blockedActions",blocked);return b;}
}
